    "text": "うちの雑誌の読者層が三四十代の女性ですから、女性目線で見たお勧めの情報はいつも好評なんで、ファッション、文化、美容と健康について取り上げていただけませんか。ページ数は写真を含めて2ページから3ページと言ったところです。",
